"""Render only: uses saved results without rerunning simulation."""
from pathlib import Path
import json
import numpy as np
import pandas as pd
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
P=Path(__file__).resolve().parent
d=pd.read_csv(P/'results.csv'); protocol=json.loads((P/'protocol.json').read_text())
S=['Normal','Moderate Congestion']; M=['FCFS','CTAS','Predictive']
def row(s,m,k,base=None):
    q=d[(d.scenario==s)&(d.method==m)&(d.metric==k)&(d.record_type==('paired_difference' if base else 'summary'))]
    if base: q=q[q.baseline==base]
    return q.iloc[0]
def fmt(r): return f'{r.value:.2f} [{r.ci95_low:.2f}, {r.ci95_high:.2f}]'
def table(headers,rows): return '| '+' | '.join(headers)+' |\n| '+' | '.join(['---']*len(headers))+' |\n'+''.join('| '+' | '.join(map(str,r))+' |\n' for r in rows)
kpis=[('avg_wait_minutes','Overall wait (min)'),('urgent_wait_minutes','CTAS 1–2 wait (min)'),('p90_wait_minutes','90th-percentile wait (min)'),('ed_utilization_pct','ED utilization (%)'),('icu_utilization_pct','ICU utilization (%)'),('completed_in_window','Completed in 21 days'),('waiting_backlog_end','Waiting at end'),('in_service_end','In service at end'),('unfinished_end','Total unfinished at end')]
r=row(S[1],'CTAS','urgent_wait_minutes','FCFS'); total=row(S[1],'CTAS','avg_wait_minutes','FCFS')
pred=row(S[1],'Predictive','urgent_wait_minutes','CTAS'); pall=row(S[1],'Predictive','avg_wait_minutes','CTAS')
finding=f'Under Moderate Congestion, CTAS Priority reduced simulated CTAS 1–2 mean waiting time from {r.baseline_mean:.1f} to {r.method_mean:.1f} minutes ({-r.relative_change_pct:.1f}% lower; paired difference {r.value:.1f} minutes, 95% CI {r.ci95_low:.1f} to {r.ci95_high:.1f}). Overall mean wait increased from {total.baseline_mean:.1f} to {total.method_mean:.1f} minutes (difference {total.value:.1f}, 95% CI {total.ci95_low:.1f} to {total.ci95_high:.1f}). This is a scheduling trade-off in synthetic data, not evidence of better clinical outcomes.'
text=['# ED scheduling: urgency prioritization has a measurable trade-off','Prepared 2026-11-01. Synthetic experiment; 10 independent seeds per scenario, 60 runs total.','## Main result',finding+' [Source: results.csv, paired_difference rows.]',f'Predictive Priority versus CTAS alone changed urgent mean wait by {fmt(pred)} minutes and overall mean wait by {fmt(pall)} minutes. The reservation policy did not provide a broad waiting-time improvement; retain the negative results rather than claim an AI gain.','![Scheduling comparison](comparison.png)','## Capacity-based scenarios', 'Both scenarios use 50 ED beds, 20 ICU beds, 8 physicians (15-minute initial assessments), 22 triage nurses (uniform 3–10 minutes), lab throughput 22/hour and imaging throughput 14/hour. CTAS 1–5 proportions are 5.26%, 21.05%, 31.58%, 26.32%, 15.79%. These are inherited experimental assumptions, not Ontario estimates. ED/ICU are separate routing pools, not a modeled ED-to-inpatient pathway.']
text.append(table(['Scenario','Target ED load','Expected patients/day','Actual patients/day, mean [95% CI]','ICU offered load','Realized ED service load'],[[s,f"{a['target_ed_load']*100:.1f}%",f"{a['expected_patients_day']:.2f}",fmt(row(s,'FCFS','patients_per_day')),f"{a['icu_offered_load']*100:.2f}%",fmt(row(s,'FCFS','ed_realized_offered_load_pct'))+'%'] for s,a in zip(S,protocol['scenarios'])]))
text.extend(['Arrival calculation: for each CTAS level, calculate the exact expectation of the **clamped** lognormal service time, including probability mass at its bounds. Means for levels 1–5 are '+', '.join(f'{protocol["clamped_service_means"][str(k)]:.2f}' for k in range(1,6))+' minutes. Weight by CTAS mix and routing probability (ICU probability 70%, 15%, 0%, 0%, 0%). Each arrival contributes 172.356 expected ED bed-minutes and 14.900 ICU bed-minutes. Thus **daily arrivals = target ED load × 50 × 1,440 / 172.356**, and ICU offered load = daily arrivals × 14.900 / (20 × 1,440). Offered load is service demand/capacity, not observed occupancy.', 'The existing normalized hourly shape and 1.2 peak multiplier are retained. Divide the per-level base hourly rate by mean weekday multiplier (1.00714) so a full week has the target daily average. Independent hourly Poisson counts fluctuate around that mean. Average physician, triage nurse, lab and imaging offered loads are respectively '+ '; '.join(f"{a['scenario']}: "+', '.join(f"{100*a[k]:.1f}%" for k in ['physician_offered_load','nurse_offered_load','lab_offered_load','imaging_offered_load']) for a in protocol['scenarios'])+'. Peak-period demand can exceed capacity even when average offered load is below 100%.','## Five KPIs and paired comparisons','Values below are equal-weight means across independent seeds, with seed-level Student-t 95% confidence intervals. Percentile results are means of each seed’s patient-level 90th percentile, not a pooled percentile.'])
for s in S:
    text += [f'### {s}',table(['Metric','FCFS [95% CI]','CTAS [95% CI]','Predictive [95% CI]'],[[label]+[fmt(row(s,m,k)) for m in M] for k,label in kpis])]
    text.append(table(['Metric','CTAS − FCFS','Predictive − FCFS','Predictive − CTAS'],[[label]+[fmt(row(s,m,k,b)) for b,m in [('FCFS','CTAS'),('FCFS','Predictive'),('CTAS','Predictive')]] for k,label in kpis]))
text += ['Differences are method minus baseline: negative waiting differences mean shorter waits; utilization differences are percentage points. Each interval uses ten paired seed differences (9 degrees of freedom). All relative percentage changes are also in results.csv. Intervals are descriptive and unadjusted for multiple comparisons; ten seeds limit precision. No individual patients are treated as independent experiment replicates.','## Window, backlog and validity','Arrivals span January 5–February 9, 2026 (35 synthetic days). January 5–12 is warm-up; January 12–February 2 is the 21-day measurement window; another seven arrival days prevent an artificially empty tail. The engine drains all generated patients. Wait outcomes include every measurement-window arrival, including those starting service after the window. Occupancy and completions use calendar time and include warm-up carry-in.',table(['Scenario / method','Waiting at start → end','Backlog trend, patients/week [95% CI]','Last − first week mean wait, min [95% CI]'],[[s+' / '+m,f"{row(s,m,'waiting_backlog_start').value:.1f} → {row(s,m,'waiting_backlog_end').value:.1f}",fmt(row(s,m,'weekly_backlog_slope')),fmt(row(s,m,'last_minus_first_week_wait'))] for s in S for m in M]),'Backlog trend fits four weekly snapshots at the same weekday/time per seed; wait drift compares the first and last complete measurement weeks. These are finite-window diagnostics, not proof of stationary behavior. End-of-window queues are real unresolved work and must not be described as zero backlog. Large cyclic queues may remain despite subcritical average offered load. Their plausibility for an actual hospital has not been established.']
seed=d[d.record_type=='seed']
guard=seed[seed.metric=='cohort_service_after_guard'].value.max(); extension=seed[seed.metric=='max_service_extension_minutes'].value.max()
text += [f'All measurement patients started service before guard arrivals stopped (maximum count beyond guard: {guard:.0f}); the outcome estimates therefore do not benefit from turning off arrivals. The largest diagnostic-induced bed-service extension was {extension:.3g} minutes (numerical rounding only), supporting the service-demand load calculation. All runs passed timestamp ordering, resource-capacity interval, reservation accounting and patient-conservation checks. For each run: carry-in + arrivals = completions during window + unfinished patients at end. Input stream SHA-256 values match across all three methods within each scenario/seed.','**Definitions:** waiting = arrival to joint bed/initial physician assessment start, including triage and queues; it is not a CIHI arrival-to-physician measure. Urgent wait pools individual CTAS 1–2 patients within each seed. ED/ICU utilization = occupied bed-minutes overlapping the measurement window / (beds × 21 × 1,440). Completed = any patient departing within the window; remaining backlog is reported both as waiting and total unfinished (waiting plus in service).','**Policy:** FCFS and CTAS share resources and nonpreemptive service. CTAS sorts by level then arrival. Predictive uses CTAS plus the existing forecast-driven bed reservations (threshold 0.8 expected urgent arrivals, 30-minute expiration, 15-minute checks). The frozen research predictor was reused without retraining or parameter selection on these seeds. It was trained under different load conditions, so this is also a transfer test; no new forecast-accuracy claim is made.','## Reproduce and inspect','From the repository root, run `python reports/portfolio_result/run_analysis.py`, then `python reports/portfolio_result/build_report.py`. The simulation runner refuses to overwrite results.csv; reproduce in a separate repository copy with a fresh output directory. The report builder only renders saved results. The existing research predictor at `reports/simulation_validation/development/predictor.pkl` is required; it is locally available but ignored by Git. Protocol.json records its SHA-256, source hashes, exact seeds, capacities, rates, dates and package versions. No new model file or training is required.', '`results.csv` contains seed-level values, summaries and paired differences, distinguished by record_type; do not add these record types together. `seed_results.partial.csv` is a retained execution checkpoint, not the authoritative final result. `validation.json` records completed checks and historical file preservation. [Source code](run_analysis.py), [configuration](protocol.json), [results](results.csv), [validation](validation.json).','**Scope:** capacity-based synthetic scenarios, not calibrated Ontario hospitals. No CIHI/NACRS aggregate statistics were used here. Routing, staffing, service distributions, absence of abandonment/boarding and strict priority limit realism. The finding supports a portfolio demonstration of experimental design and statistical analysis; it does not establish clinical safety, patient benefit or a deployable scheduling recommendation. Historical results were preserved, with no commit or push.']
text.insert(text.index('## Window, backlog and validity')+1,'No scenario/method had a weekly backlog-trend or first-to-last-week wait interval excluding zero. This is no clear evidence of accumulating overload over the measured weeks, not confirmation of long-run stability. Moderate CTAS runs still averaged 298 waiting patients at the final midnight snapshot and a 26-hour 90th-percentile wait. These substantial queues limit the realism claim, especially because patients never abandon the queue. The names “Normal” and “Moderate Congestion” describe offered-load targets only.')
text.append('Daily patient counts for all 420 measured scenario/seed days are in [daily_arrivals.csv](daily_arrivals.csv). Run `python reports/portfolio_result/verify_results.py` to regenerate streams and independently check their hashes, daily totals, service expectations by numerical integration, and every paired confidence interval; it does not rerun the scheduling experiment. The existing regression suite also passed: 33 tests.')
(P/'analysis.md').write_text('\n\n'.join(text)+'\n',encoding='utf-8')
bullets=[f'Analyzed 60 paired ED scheduling simulations in Python across two capacity-based scenarios and 10 random seeds, reporting five operational KPIs with 95% confidence intervals.',f'Quantified a synthetic scheduling trade-off: CTAS priority reduced urgent-patient mean wait by {-r.relative_change_pct:.0f}% ({r.baseline_mean:.0f} to {r.method_mean:.0f} minutes) under moderate congestion, while increasing overall wait by {total.value:.0f} minutes.']
(P/'resume_bullets.md').write_text('# Junior Data Analyst resume bullets\n\n'+'\n'.join('- '+b for b in bullets)+'\n\nUse “synthetic” when presenting this result; no real-hospital or clinical improvement was established. See analysis.md for paired uncertainty and assumptions.\n',encoding='utf-8')
fig,axes=plt.subplots(2,3,figsize=(13,7.5),layout='constrained')
colors=['#446580','#b06626','#44816b']
for i,s in enumerate(S):
    for j,(k,title) in enumerate(kpis[:3]):
        ax=axes[i,j]; rr=[row(s,m,k) for m in M]; vals=np.array([r.value for r in rr]); low=np.array([r.ci95_low for r in rr]); high=np.array([r.ci95_high for r in rr])
        ax.bar(M,vals,color=colors,yerr=np.array([vals-low,high-vals]),capsize=4)
        ax.set_title(s+'\n'+title,fontsize=11); ax.set_ylabel('Minutes'); ax.set_ylim(0,max(high)*1.22)
        for n,v in enumerate(vals): ax.text(n,high[n]+max(high)*.035,f'{v:.1f}',ha='center',fontsize=10)
        ax.spines[['top','right']].set_visible(False)
fig.suptitle('Urgency priority trades shorter urgent waits for longer overall waits',fontsize=15)
fig.supxlabel('Synthetic data · 50 ED / 20 ICU beds · 10 paired seeds · 21 measured days after 7-day warm-up\nError bars: seed-level 95% t intervals; source: results.csv',fontsize=10)
fig.savefig(P/'comparison.png',dpi=180)
print(finding)
